    "justification": "Human samples profiled by microarray (Affymetrix U133A) measuring RNA expression."
  },
  "q2_target_disease": {
    "answer": "No",
    "evidence": "Title/Description: 'Gene expression patterns in peripheral blood correlate with the extent of coronary artery disease' and text describes patients undergoing coronary angiography and CAD index (CADi).",
    "justification": "The study investigates coronary artery disease (CAD), not ALS-FTD."
  },
  "q3_human_cns_tissue": {
    "answer": "No",
    "evidence": "Description: RNA extracted from circulating leukocytes; samples are peripheral blood leukocytes. 'Organism part' not specified as CNS; sample source described as circulating leukocytes.",
    "justification": "Samples are peripheral blood leukocytes, not human brain/CNS tissue."
  },
  "q4_non_clinical": {
    "answer": "No",
    "evidence": "Description indicates RNA from patients' circulating leukocytes collected at coronary angiography; no mention of in vitro cell lines or disease models.",
    "justification": "This is an in vivo clinical blood study, not patient-derived cell lines or experimental models."
  },
  "q5_case_control_design": {
    "answer": "Yes",
    "evidence": "RNA was extracted from 110 patients with CAD (CADi>23) and from 112 partially matched controls without CAD (CADi=0); design listed as 'parallel group design'.",
    "justification": "There are defined case (CAD) and control (no CAD) groups appropriate for case/control comparison."
  },
  "q6_irrelevant_brain_region": {
    "answer": "No",
    "evidence": "Samples are circulating leukocytes (peripheral blood); no brain regions are sampled or listed.",
    "justification": "The dataset does not sample any brain regions (so it does not involve brain regions irrelevant to ALS-FTD — it involves no CNS tissue at all)."
  },
  "q7_incompatible_technology": {
    "answer": "No",
    "evidence": "Study type: transcription profiling by array; Affymetrix U133A microarrays used; Assay by Molecule: RNA assay.",
    "justification": "Technology is microarray expression profiling, which is compatible with inclusion (but other criteria still exclude)."
  },
  "q8_inclusion_justification": {
    "justification": "Exclude. Although this is a human microarray case/control study, it investigates coronary artery disease using peripheral blood leukocytes rather than ALS-FTD and does not include CNS/brain tissue relevant to ALS-FTD."
  },
  "q9_include_dataset": {
    "answer": "No"
  }
}

